-- =============================================================================
-- AMEXAN Medical Knowledge Compiler - Respiratory Master Matrix
-- Objective, queryable tracking of every respiratory-domain item and its
-- completeness ladder (MISSING -> SEEDED -> STRUCTURED -> GROUNDED ->
-- EXECUTABLE -> VERIFIED). A project instrument - NOT governed clinical truth.
-- GENERATED FILE - do not edit by hand. Regenerate with:
--   python knowledge-compiler/build_respiratory_master_matrix.py <out>
-- =============================================================================

CREATE SCHEMA IF NOT EXISTS tracking;

CREATE TABLE IF NOT EXISTS tracking.respiratory_master_matrix (
    id            uuid PRIMARY KEY,
    family_code   text NOT NULL,
    family_name   text NOT NULL,
    item_code     text NOT NULL UNIQUE,
    item_name     text NOT NULL,
    population    text NOT NULL DEFAULT 'B',
    status        text NOT NULL DEFAULT 'MISSING'
        CHECK (status IN ('MISSING','SEEDED','STRUCTURED','GROUNDED','EXECUTABLE','VERIFIED')),
    source_ground text,
    notes         text,
    updated_at    timestamptz NOT NULL DEFAULT now()
);

  ON CONFLICT DO NOTHING;
